const num=(x,d=1)=>Number(x).toLocaleString('en-CA',{maximumFractionDigits:d});
const KEY='bgsd-float-lab-v1';
const defaults={mode:'compare',compare:{kind:'solids',a:'oak',b:'concrete',fa:'water',fb:'water',volume:100,salt:10,measured:false,tested:false,prediction:'',challenge:'explore',forces:false},layers:{entries:[],selected:'water',portion:80,salt:10,phase:'early',prediction:'',sample:'wax',released:false,challenge:'explore'},drop:{percent:10,volume:2,released:false,prediction:'',forces:false,showDensity:false,challenge:'suspend'},boat:{width:10,height:2,cargo:100,fluid:'water',tested:false,prediction:'',challenge:'200'},trials:[],paused:false};
