const option=(values,id)=>values.map(v=>`<option value="${v.id}" ${id===v.id?'selected':''}>${esc(v.name)}</option>`).join('');
function challengeSelect(mode,items){return `<div class="challenge"><label for="challenge">Investigation</label><select id="challenge" data-state="${mode}.challenge">${items.map(([id,s])=>`<option value="${id}" ${S[mode].challenge===id?'selected':''}>${s}</option>`).join('')}</select></div>`;}
function prediction(mode,items){return `<div class="prediction"><fieldset><legend>Your prediction</legend>${items.map(([id,text])=>`<button class="small" data-predict="${mode}:${id}" aria-pressed="${S[mode].prediction===id}">${text}</button>`).join('')}</fieldset></div>`;}
function shell(title,sub,scene,tools,investigation=''){return `<section class="investigation ${S.mode}-investigation" aria-labelledby="investigation-title"><div class="lab-stage"><div class="intro"><div><h1 id="investigation-title">${title}</h1><p>${sub}</p></div>${investigation}</div>${scene}</div><div class="lab-tools">${tools}<p id="feedback" class="feedback" aria-live="polite">${esc(notice)}</p></div></section>`;}
