if(act==='compare-reset'){S.compare.tested=false;S.compare.measured=false;notice='';resetBodies();render();}
if(act==='pour'){let l=S.layers;if(l.entries.reduce((a,e)=>a+e.volume,0)+l.portion>600)return;currentPour=entry(l.selected,l.portion,l.salt);l.entries.push(currentPour);layerTween=reduced?1:0;l.phase='early';l.released=false;notice=`Poured ${l.portion} mL of ${fluid(l.selected,l.salt).name.toLowerCase()}. Observe its position before keeping or revising your explanation.`;render();announce(notice);}
if(act==='wait'||act==='stir'){currentPour=null;layerTween=1;let l=S.layers;l.entries=blendLayers(l.entries,act==='stir');l.phase=act==='stir'?'stirred':'standing';notice=act==='stir'?'Water-compatible liquids blend. Oil separates again. In this model the waiting time is shortened.':'Adjacent water-compatible liquids blend; oil can keep water and alcohol apart when it lies between them.';render();announce(notice);}
if(act==='layer-object'){S.layers.released=true;layerObjectProgress=reduced?1:0;let m=MATERIALS.find(m=>m.id===S.layers.sample);const eq=layerEquilibrium(S.layers.entries,m.rho);notice=eq.state==='bottom'?'The sample reaches the bottom. Compare its density with every liquid in the stack.':eq.state==='surface'?'The sample floats at the upper surface. Explain why.':'The sample settles within the stack. Its weight balances buoyant forces from the liquid around it.';render();announce(notice);}
if(act==='layer-reset'){currentPour=null;layerTween=1;S.layers.entries=[];S.layers.phase='early';S.layers.released=false;notice='';render();}
if(act==='release'){S.drop.released=true;dropBody={z:-.07,v:0};dropSuccess=0;dropTime=0;notice='Drop released at the centre. Observe its motion, then adjust the mixture in small steps.';render();announce(notice);}
if(act==='boat-test'){S.boat.tested=true;boatProgress=0;const b=S.boat,m=boatModel(b.width,b.height,b.cargo),goal=Number(b.challenge);notice=m.flooded?'Water comes over the rim and fills the hull. Reshape the same clay, reduce the cargo, or both.':(goal&&b.cargo>=goal?'Challenge met! ':'')+'The hull floats. Compare this design with a trial using the same cargo.';render();announce(notice);}
if(act==='boat-reset'){S.boat.tested=false;notice='';render();}
