function download(name,content,mime){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const quote=s=>'"'+String(s??'').replace(/"/g,'""')+'"';let rows=[['Investigation','Prediction','Measurements and observations','Explanation'],...S.trials.map(t=>[t.title,t.prediction,Object.entries(t.data).map(([k,v])=>k+': '+v).join('; '),t.reflection])];download('Float-Lab-Trials.csv','\ufeff'+rows.map(r=>r.map(s=>quote(/^[=+@-]/.test(String(s))?'\''+s:s)).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function trialHTML(t,i){return `<article class="trial"><h3>${i+1}. ${esc(t.title)}</h3><dl><dt>Prediction</dt><dd>${esc(t.prediction)}</dd>${Object.entries(t.data).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><label>My explanation: what evidence supports it?<textarea maxlength="6000" data-reflection="${t.id}">${esc(t.reflection)}</textarea></label></article>`;}
